/* ---------- title screen: black-and-white photo (AI-generated by the author), film grain, English title ---------- */
function drawSplash(c,w,h,img){const port=h>w*1.15;c.fillStyle='#000';c.fillRect(0,0,w,h);
  let dx,dy,dw,dh;if(port){dw=w*1.55;dh=dw*img.height/img.width;dx=w/2-dw*.45;dy=h*.36;}else{const s=Math.max(w/img.width,h/img.height);dw=img.width*s;dh=img.height*s;dx=(w-dw)/2;dy=(h-dh)/2;}
  c.drawImage(img,dx,dy,dw,dh);
  try{const im=c.getImageData(0,0,w,h),d=im.data;let s=7;const rnd=()=>{s=(s*16807)%2147483647;return s/2147483647;};
    for(let i=0;i<d.length;i+=4){let y=d[i]*.3+d[i+1]*.59+d[i+2]*.11;y=255/(1+Math.exp(-(y-125)/42));y+=(rnd()-.5)*28;d[i]=d[i+1]=d[i+2]=y<0?0:y>255?255:y;}c.putImageData(im,0,0);}catch(e){}
  if(port){let g=c.createLinearGradient(0,dy,0,dy+dh*.22);g.addColorStop(0,'#000');g.addColorStop(1,'rgba(0,0,0,0)');c.fillStyle=g;c.fillRect(0,dy-2,w,dh*.22+2);
    g=c.createLinearGradient(0,dy+dh*.72,0,dy+dh);g.addColorStop(0,'rgba(0,0,0,0)');g.addColorStop(1,'#000');c.fillStyle=g;c.fillRect(0,dy+dh*.72,w,dh*.28+2);}
  else{let g=c.createLinearGradient(w,0,w*.55,0);g.addColorStop(0,'rgba(0,0,0,.85)');g.addColorStop(1,'rgba(0,0,0,0)');c.fillStyle=g;c.fillRect(w*.55,0,w*.45,h);}
  const v=c.createRadialGradient(w/2,h*.6,Math.min(w,h)*.3,w/2,h*.6,Math.max(w,h)*.8);v.addColorStop(0,'rgba(0,0,0,0)');v.addColorStop(1,'rgba(0,0,0,.7)');c.fillStyle=v;c.fillRect(0,0,w,h);
  const T=port?w*.12:Math.min(w*.06,h*.1);c.direction='ltr';c.textAlign=port?'center':'right';const cx=port?w/2:w*.95;let ty=port?h*.14:h*.2;const F='"Roboto Condensed", Arial, sans-serif';
  const sp=v=>{try{c.letterSpacing=v;}catch(e){}};
  c.font=`700 ${T*.34}px ${F}`;c.fillStyle='#d23b2e';sp(`${T*.2}px`);c.fillText('PROJECT',cx,ty);
  ty+=T*1.05;c.font=`700 ${T*1.05}px ${F}`;sp(`${T*.06}px`);
  for(const ln of ['END OF','TERROR']){c.lineWidth=T*.06;c.strokeStyle='rgba(0,0,0,.9)';c.strokeText(ln,cx,ty);c.fillStyle='#f2f0ea';c.fillText(ln,cx,ty);ty+=T*1.08;}
  sp('0px');c.fillStyle='#d23b2e';c.fillRect(port?cx-T*1.4:cx-T*2.8,ty-T*.62,T*2.8,Math.max(2,T*.045));
  c.font=`${T*.27}px "PT Mono", monospace`;sp(`${T*.08}px`);c.fillStyle='rgba(235,235,230,.85)';c.fillText('OPERATION RESHET',cx,ty-T*.2);sp('0px');}
const SPLASH_IMG='data:image/jpeg;base64,__SPLASH_B64__';
function showSplash(){const el=$('#splash'),cv=$('#spC'),img=new Image();let ok=false;
  const paint=()=>{if(el.hidden||!ok)return;const d=Math.min(2,window.devicePixelRatio||1),w=innerWidth,h=innerHeight;cv.width=Math.round(w*d);cv.height=Math.round(h*d);cv.style.width=w+'px';cv.style.height=h+'px';drawSplash(cv.getContext('2d'),cv.width,cv.height,img);};
  el.hidden=false;const fl=Promise.race([Promise.all(['700 40px "Roboto Condensed"','40px "PT Mono"'].map(f=>document.fonts.load(f,'PROJECT'))).catch(()=>{}),new Promise(r=>setTimeout(r,2500))]);img.onload=()=>{fl.then(()=>{ok=true;paint();});};img.src=SPLASH_IMG;addEventListener('resize',paint);el.onclick=()=>{el.hidden=true;removeEventListener('resize',paint);};}

